import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { it } from 'vitest';
import { issueBrief } from './brief.js';
import { runDossierCli } from './cli.js';
import { NO_PROVIDER_STATEMENTS, type GateSources, type GateState } from './gate-sources.js';
import type { PinnedObjectReader } from './git-object-reader.js';
import { launchFormRefusal, writeLaunchedMarker } from './launched.js';
import { parseRunConfig } from './run-config.js';
import { NO_WORK_ITEM_REASON, encodeRunRecord, type RunSubject } from './run-record.js';
import { launchForm, sessionPrompt } from './session-handover.js';

// syzygy-bpyt.8.8 round-2 old-versus-new differential harness (not committed as a test). Public entry points only, present at both the merge
// base and the fix: allow-execution (CLI), launchFormRefusal, launchForm on a handed-over inventory session, issueBrief with the
// permitting arm off (bytes on fixed paths) and on (fixture ports). One fresh run directory per variant and probe. B88_ONLY_VARIANT and
// B88_ONLY_PROBE restrict a run to one variant and one probe, so a variant that blocks a reader runs each probe in its own process.

const OUT = process.env['B88_OUT']!;
const BASE = process.env['B88_BASE']!;
const ONLY_VARIANT = process.env['B88_ONLY_VARIANT'];
const ONLY_PROBE = process.env['B88_ONLY_PROBE'];
const SKIP = (process.env['B88_SKIP'] ?? '').split('|').filter((name) => name !== '');
const probing = (probe: string): boolean => ONLY_PROBE === undefined || ONLY_PROBE === probe;
const REAL_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const NOW = Date.UTC(2026, 9, 7, 12, 0, 0);
const RUN_ID = `run-${'a'.repeat(32)}`;
const ALL = ['owner-started-session', 'owners-own-host', 'owner-attends'];
const GIT_ENV = { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null', GIT_AUTHOR_DATE: '2026-10-01T00:00:00Z', GIT_COMMITTER_DATE: '2026-10-01T00:00:00Z' };
const sha = (bytes: Buffer | string): string => createHash('sha256').update(bytes).digest('hex');

const VARIANTS: readonly [string, (marker: string, run: string) => void][] = [
  ['absent', () => undefined],
  ['launched (written by writeLaunchedMarker)', (_m, run) => writeLaunchedMarker(run, RUN_ID, NOW)],
  ['launched format, another runId', (m) => fs.writeFileSync(m, JSON.stringify({ format: 'polaris-dossier-launched/1', runId: 'run-other' }))],
  ['empty file', (m) => fs.writeFileSync(m, '')],
  ['invalid JSON', (m) => fs.writeFileSync(m, '{"format": "polaris-dossier-launched/1"')],
  ['JSON null', (m) => fs.writeFileSync(m, 'null')],
  ['JSON array', (m) => fs.writeFileSync(m, '[]')],
  ['JSON string', (m) => fs.writeFileSync(m, '"polaris-dossier-launched/1"')],
  ['another format', (m) => fs.writeFileSync(m, '{"format": "polaris-dossier-launched/2"}')],
  ['no format', (m) => fs.writeFileSync(m, '{"runId": "run-x"}')],
  ['non-string format', (m) => fs.writeFileSync(m, '{"format": 1}')],
  ['byte-order mark before the marker', (m) => fs.writeFileSync(m, '\uFEFF{"format": "polaris-dossier-launched/1"}')],
  ['directory', (m) => fs.mkdirSync(m)],
  ['dangling symbolic link', (m, run) => fs.symlinkSync(path.join(run, 'nowhere.json'), m)],
  ['mode 000 marker', (m) => { fs.writeFileSync(m, '{"format": "polaris-dossier-launched/1"}'); fs.chmodSync(m, 0o000); }],
  ['symbolic link to a valid marker', (m, run) => { const other = path.join(path.dirname(run), 'elsewhere'); fs.mkdirSync(other, { recursive: true }); writeLaunchedMarker(other, RUN_ID, NOW); fs.symlinkSync(path.join(other, 'launched.json'), m); }],
  ['valid marker padded past 4096 bytes', (m) => fs.writeFileSync(m, JSON.stringify({ format: 'polaris-dossier-launched/1', runId: RUN_ID, pad: 'x'.repeat(4096) }))],
  ['FIFO', (m) => execFileSync('mkfifo', [m])],
  ['symbolic link to /dev/zero', (m) => fs.symlinkSync('/dev/zero', m)],
];

const OK: GateState = { state: 'ok', record: 'FIXTURE-ACT' };
const REV = '498ecd0d6d007db11ddb3aea9428552598a78622';
const FIXED_SUBJECT: RunSubject = {
  repository: { url: 'https://github.com/redis/redis', repositoryId: 'redis-redis' },
  clone: { path: '/srv/clones/redis', declaredBy: 'operator', label: 'Inferred', use: 'read' },
  pinnedRevision: { commit: REV, label: '8.10.2', consentRecord: 'PUBLIC-OBS-REDIS-2026-10-03@0.1.0-candidate.7', pinnedAt: '2026-10-07T10:00:00.000Z' },
  startGates: { registryEntry: 'REGISTRY-ACT-FIXTURE', screeningPolicy: 'POLICY-ACT-FIXTURE' },
  governed: { kind: 'non-governed', because: ['fixture'] },
  providerStatement: null,
  workItem: { identity: null, reason: NO_WORK_ITEM_REASON },
};
const sourcesFor = (commit: string): GateSources => ({
  recordsRoot: REAL_ROOT,
  repositoryIdsFor: async () => ['redis-redis'],
  consentedRevisionsFor: async () => [{ label: '8.10.2', commitId: commit }],
  observationConsentFor: async (_id, revision) => (revision === commit ? { satisfied: true, record: 'PUBLIC-OBS-REDIS-2026-10-03@0.1.0-candidate.7' } : { satisfied: false, why: 'not named' }),
  registryEntry: async () => OK,
  screeningPolicy: async () => OK,
  d9: async () => OK,
  rfc720Ruling: async () => OK,
  projectInput: { drawerFor: async () => ({ stated: true, drawer: 'absent', record: 'PROJECT-INPUT-FIXTURE@1' }) },
  providerStatements: NO_PROVIDER_STATEMENTS,
});
const openReader = () => ({ listTree: async () => [{ path: 'src/server.c' }] }) as unknown as PinnedObjectReader;
const config = () => {
  const parsed = parseRunConfig(JSON.stringify({
    operator: 'Tzeusy', agentTool: 'claude-code', agentToolVersion: '2.1.0', agentProvider: 'anthropic', model: 'claude-opus-5-5',
    deadline: 'PT1H', agentTokenBudget: 100_000, maxRepairCycles: 3, maxQuestions: 2, audience: 'an operator', operatorIsOwner: true,
  }));
  if (!parsed.ok) throw new Error('fixture configuration refused');
  return parsed.config;
};
/** A fresh run directory at a fixed path, so the bytes a brief writes compare across the two trees. */
const fixedRun = (probe: string, subject: RunSubject = FIXED_SUBJECT): string => {
  const root = path.join(BASE, 'runs', probe);
  fs.rmSync(root, { recursive: true, force: true });
  const run = path.join(root, RUN_ID);
  fs.mkdirSync(run, { recursive: true });
  fs.writeFileSync(path.join(run, 'run.json'), encodeRunRecord(config(), subject));
  return run;
};
const plant = (variant: (m: string, r: string) => void, run: string): void => variant(path.join(run, 'launched.json'), run);
const unplant = (run: string): void => { try { fs.chmodSync(path.join(run, 'launched.json'), 0o600); } catch { /* absent or a link */ } };

it('differential', async () => {
  // A real pinned clone for the hand-over probe: launch-form needs a handed-over inventory session.
  const origin = path.join(BASE, 'origin');
  fs.rmSync(origin, { recursive: true, force: true });
  fs.mkdirSync(path.join(origin, 'src'), { recursive: true });
  const git = (...args: string[]): string => execFileSync('git', ['-C', origin, ...args], { encoding: 'utf8', env: GIT_ENV }).trim();
  git('init', '-q', '-b', 'main');
  fs.writeFileSync(path.join(origin, 'src', 'kestrel.c'), 'int main(void) { return 0; }\n');
  git('add', '-A');
  git('-c', 'user.name=t', '-c', 'user.email=t@example.invalid', 'commit', '-q', '-m', 'fixture');
  const commit = git('rev-parse', 'HEAD');
  const gitSources = sourcesFor(commit);

  const rows: Record<string, unknown>[] = [];
  for (const [name, variant] of VARIANTS) {
    if ((ONLY_VARIANT !== undefined && ONLY_VARIANT !== name) || SKIP.includes(name)) continue;
    const row: Record<string, unknown> = { variant: name };

    // allow-execution through the CLI.
    if (probing('allowExecution')) {
      const run = fixedRun('allow');
      plant(variant, run);
      let stdout = '';
      const code = await runDossierCli(['allow-execution', run, '--revision', REV, '--declare', ALL.join(','), '--json'], { stdout: (t) => { stdout += t; }, stderr: () => undefined }, { sources: sourcesFor(REV), now: () => NOW, openReader });
      const doc = JSON.parse(stdout);
      row['allowExecution'] = { exit: code, outcome: doc.outcome, stage: doc.stage ?? null, reason: doc.reason ?? null, choiceWritten: fs.existsSync(path.join(run, 'execution-choice.json')) };
      unplant(run);
    }

    // launchFormRefusal, the gate inventory-of-record and the review verdict reader also call.
    if (probing('launchFormRefusal')) {
      const run = fixedRun('refusal');
      plant(variant, run);
      row['launchFormRefusal'] = {
        terminal: launchFormRefusal(run, { value: 'terminal', declaredBy: 'operator', label: 'Inferred' }),
        bang: launchFormRefusal(run, { value: 'bang', declaredBy: 'operator', label: 'Inferred' }),
        syzygyLaunched: launchFormRefusal(run, { value: 'syzygy-launched', declaredBy: 'syzygy', label: 'Observed' }),
      };
      unplant(run);
    }

    // launch-form on a handed-over inventory session: the marker is planted after the hand-over.
    if (probing('launchForm')) {
      const clone = path.join(BASE, 'runs', 'handover-clone');
      fs.rmSync(clone, { recursive: true, force: true });
      execFileSync('git', ['clone', '-q', '--no-hardlinks', origin, clone], { env: GIT_ENV });
      const run = fixedRun('handover', { ...FIXED_SUBJECT, clone: { ...FIXED_SUBJECT.clone, path: clone }, pinnedRevision: { ...FIXED_SUBJECT.pinnedRevision, commit } });
      const brief = await issueBrief(run, { sources: gitSources, now: () => NOW });
      if (!brief.ok) throw new Error(`fixture brief refused: ${brief.refusal.reason}`);
      fs.mkdirSync(path.join(run, 'drafts'));
      fs.writeFileSync(path.join(run, 'drafts', 'rev-0.json'), JSON.stringify({ sessionId: 'author-1', title: 'draft' }));
      fs.writeFileSync(path.join(run, 'drafts', 'next.json'), JSON.stringify({ sessionId: 'author-1', title: 'draft' }));
      const handed = await sessionPrompt(run, { role: 'inventory' }, { sources: gitSources, now: () => NOW + 60_000 });
      if (!handed.ok) throw new Error(`fixture session-prompt refused: ${handed.refusal.reason}`);
      plant(variant, run);
      const result = await launchForm(run, { role: 'inventory', form: 'terminal' }, { sources: gitSources, now: () => NOW + 60_000 });
      row['launchForm'] = result.ok
        ? { ok: true, form: result.report.form, recordWritten: fs.existsSync(path.join(run, 'inventory', 'session-1.launch.json')) }
        : { ok: false, stage: result.refusal.stage, reason: result.refusal.reason, recordWritten: fs.existsSync(path.join(run, 'inventory', 'session-1.launch.json')) };
      unplant(run);
    }

    // issueBrief with the permitting arm off: what this build ships.
    if (probing('briefArmOff')) {
      const run = fixedRun('brief-off');
      plant(variant, run);
      const result = await issueBrief(run, { sources: sourcesFor(REV), openReader, now: () => NOW });
      row['briefArmOff'] = result.ok
        ? { ok: true, briefMdSha256: sha(fs.readFileSync(path.join(run, 'brief.md'))), briefJsonSha256: sha(fs.readFileSync(path.join(run, 'brief.json'))), executionRule: JSON.parse(fs.readFileSync(path.join(run, 'brief.json'), 'utf8')).executionRule }
        : { ok: false, stage: result.refusal.stage };
      unplant(run);
    }

    // issueBrief with the arm switched on through fixture ports (never on in this build).
    if (probing('briefArmOn')) {
      const run = fixedRun('brief-on');
      plant(variant, run);
      const choice = { recordId: 'choice-1', command: 'allow-execution' as const, runId: RUN_ID, revision: REV, recordedAt: '2026-10-07T11:59:00.000Z', declarations: { ownerStartedSession: true, ownersOwnHost: true, ownerAttends: true } };
      const result = await issueBrief(run, { sources: sourcesFor(REV), openReader, now: () => NOW, permitting: { enabled: true, choices: { choiceFor: async () => ({ state: 'ok' as const, choice }) }, probe: { probe: async () => ({ passed: true as const, checked: 1, source: 'fixture' }) } } });
      const rule = result.ok ? JSON.parse(fs.readFileSync(path.join(run, 'brief.json'), 'utf8')).executionRule : null;
      row['briefArmOn'] = result.ok ? { ok: true, arm: rule.arm, notPermittedBecause: rule.notPermittedBecause ?? null } : { ok: false, stage: result.refusal.stage };
      unplant(run);
    }
    rows.push(row);
  }
  fs.rmSync(path.join(BASE, 'runs'), { recursive: true, force: true });
  fs.rmSync(origin, { recursive: true, force: true });
  fs.writeFileSync(OUT, `${JSON.stringify(rows, null, 2)}\n`);
}, 300_000);

driver.text:
"""Drives the syzygy-bpyt.8.8 round-2 differential: the harness runs once per side over the variants that block no reader, and once per
(variant, probe) in its own process group, under a kill timeout, for the two that can block or exhaust the base reader. The base side
restores the subject source files from the merge base, then the fix is restored. Usage: python3 drive.py <worktree> <base> <scratch> <out.json>"""
import json, os, signal, subprocess, sys
from pathlib import Path

ROOT, BASE, SCRATCH, OUT = Path(sys.argv[1]), sys.argv[2], Path(sys.argv[3]), Path(sys.argv[4])
HERE = Path(__file__).resolve().parent
TARGET = ROOT / 'packages/polaris-dossier/src/zz-b88-differential.test.ts'
PROBES = ['allowExecution', 'launchFormRefusal', 'launchForm', 'briefArmOff', 'briefArmOn']
BLOCKING = ['FIFO', 'symbolic link to /dev/zero']
# The base reader follows the link and reads /dev/zero without bound at these three probes; they are not run at the base.
UNBOUNDED_AT_BASE = {('symbolic link to /dev/zero', p) for p in ['allowExecution', 'launchFormRefusal', 'launchForm']}
TIMEOUT = 120

def git(*args):
    return subprocess.run(['git', '-C', str(ROOT), *args], capture_output=True, text=True, check=True).stdout

SUBJECT = [f for f in git('diff', '--name-only', BASE, 'HEAD', '--', 'packages/polaris-dossier/src').split() if not f.endswith('.test.ts')]

def run(side, env_extra, out):
    env = {**os.environ, 'B88_BASE': str(SCRATCH / side), 'B88_OUT': str(out), 'CI': '1', **env_extra}
    (SCRATCH / side).mkdir(parents=True, exist_ok=True)
    proc = subprocess.Popen(['npx', 'vitest', 'run', '--project', '@syzygy/polaris-dossier', str(TARGET.relative_to(ROOT))], cwd=ROOT, env=env,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, start_new_session=True)
    try:
        log, _ = proc.communicate(timeout=TIMEOUT)
    except subprocess.TimeoutExpired:
        os.killpg(proc.pid, signal.SIGKILL)
        proc.communicate()
        return {'blocked': True, 'killedAfterSeconds': TIMEOUT}
    if not out.exists():
        return {'harnessFailed': True, 'exit': proc.returncode, 'logTail': log.decode('utf8', 'replace')[-2000:]}
    return json.loads(out.read_text())

def side(name):
    rows = {r['variant']: r for r in run(name, {'B88_SKIP': '|'.join(BLOCKING)}, SCRATCH / f'{name}-main.json')}
    for variant in BLOCKING:
        row = {'variant': variant}
        for probe in PROBES:
            if name == 'base' and (variant, probe) in UNBOUNDED_AT_BASE:
                row[probe] = {'notRun': 'the base reader follows the link and reads /dev/zero without bound'}
                continue
            result = run(name, {'B88_ONLY_VARIANT': variant, 'B88_ONLY_PROBE': probe}, SCRATCH / f'{name}-{BLOCKING.index(variant)}-{probe}.json')
            row[probe] = result[0][probe] if isinstance(result, list) else result
        rows[variant] = row
    return rows

TARGET.write_text((HERE / 'harness.test.ts').read_text())
try:
    new = side('new')
    git('checkout', BASE, '--', *SUBJECT)
    try:
        old = side('base')
    finally:
        git('checkout', 'HEAD', '--', *SUBJECT)
finally:
    TARGET.unlink()
OUT.write_text(json.dumps({'subject': SUBJECT, 'base': BASE, 'fix': git('rev-parse', 'HEAD').strip(), 'old': old, 'new': new,
                           'trackedTreeClean': git('status', '--porcelain', '--untracked-files=no') == ''}, indent=2) + '\n')
print('done', len(old), len(new))
